import { Suspense } from 'react'
import { CardStats } from './CardStats'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { getDashboardData } from './dashboard-data'

function StatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-hidden>
      <div className="card skeleton-block" />
      <div className="card skeleton-block" />
    </div>
  )
}

function ChartSkeleton() {
  return (
    <div className="chart skeleton-chart" aria-hidden>
      <div className="skeleton-line w-24" />
      <ul className="space-y-2">
        <li className="skeleton-line" />
        <li className="skeleton-line" />
        <li className="skeleton-line w-4/5" />
      </ul>
    </div>
  )
}

function InvoicesSkeleton() {
  return (
    <div className="invoices skeleton-chart" aria-hidden>
      <div className="skeleton-line w-32" />
      <ul className="space-y-2">
        <li className="skeleton-line" />
        <li className="skeleton-line" />
        <li className="skeleton-line w-3/4" />
      </ul>
    </div>
  )
}

async function StatsSection() {
  const data = await getDashboardData()
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function ChartSection() {
  const data = await getDashboardData()
  return <RevenueChart revenue={data.revenue} />
}

async function InvoicesSection() {
  const data = await getDashboardData()
  return <LatestInvoices invoices={data.invoices} />
}

export function DashboardStreamingSections() {
  return (
    <>
      <Suspense fallback={<StatsSkeleton />}>
        <StatsSection />
      </Suspense>
      <Suspense fallback={<ChartSkeleton />}>
        <ChartSection />
      </Suspense>
      <Suspense fallback={<InvoicesSkeleton />}>
        <InvoicesSection />
      </Suspense>
    </>
  )
}

export function DashboardLoadingShell() {
  return (
    <>
      <StatsSkeleton />
      <ChartSkeleton />
      <InvoicesSkeleton />
    </>
  )
}

